      value.vessel_packets,
      value.relay_nodes,
      value.storm_routing,
    ),
    relay_state:
      droppedUnits === 0
        ? "clear"
        : value.storm_routing
          ? "storm_loss"
          : "packet_loss",
  };
};

export async function loadParley() {
  return {
    subsea_relay_reserve: (
      shorePackets: number,
      vesselPackets: number,
      relayNodes: number,
      stormRouting: boolean,
    ) => BigInt(reserve(shorePackets, vesselPackets, relayNodes, stormRouting)),
  };
}

