const theatreTurnaroundScore = (matineeShows, eveningShows, stageCrews, touringProduction) => {
  const matinees = BigInt(matineeShows);
  const evenings = BigInt(eveningShows);
  const crews = BigInt(stageCrews);
  const baseResetMinutes = matinees * 18n + evenings * 27n;
  const touringMinutes = touringProduction ? crews * 6n : 0n;
  const requiredMinutes = baseResetMinutes + touringMinutes;
  const crewCapacityMinutes = crews * 45n;
  const coveredMinutes = requiredMinutes < crewCapacityMinutes
    ? requiredMinutes
    : crewCapacityMinutes;
  const delayedMinutes = requiredMinutes > crewCapacityMinutes
    ? requiredMinutes - crewCapacityMinutes
    : 0n;
  const handoffWindows = requiredMinutes / 30n;
  return coveredMinutes + delayedMinutes * 8n + handoffWindows * 11n;
};
export async function loadParley() { return { theatre_turnaround_score: theatreTurnaroundScore }; }

