export type RequestInput = { shore_packets: number; vessel_packets: number; relay_nodes: number; storm_routing: boolean };

const calculate = (shore_packets: number, vessel_packets: number, relay_nodes: number, storm_routing: boolean) => {
  const shore_units = shore_packets * 4;
  const vessel_units = vessel_packets * 7;
  const storm_units = storm_routing ? relay_nodes * 5 : 0;
  const required_units = shore_units + vessel_units + storm_units;
  const relay_capacity_units = relay_nodes * 24;
  const forwarded_units = Math.min(required_units, relay_capacity_units);
  const dropped_units = Math.max(required_units - relay_capacity_units, 0);
  const reserve_units = Math.max(relay_capacity_units - forwarded_units, 0);

  return { shore_units, vessel_units, storm_units, required_units, relay_capacity_units, forwarded_units, dropped_units, reserve_units };
};

export const reserve = (shore_packets: number, vessel_packets: number, relay_nodes: number, storm_routing: boolean) =>
  calculate(shore_packets, vessel_packets, relay_nodes, storm_routing).reserve_units;

export const handle = (value: RequestInput) => {
  const result = calculate(value.shore_packets, value.vessel_packets, value.relay_nodes, value.storm_routing);
  return {
    packet_total: value.shore_packets + value.vessel_packets,
    ...result,
    relay_state: result.dropped_units === 0 ? "clear" : value.storm_routing ? "storm_loss" : "packet_loss",
  };
};

export async function loadParley() {
  return { subsea_relay_reserve: reserve };
}

