export type RequestInput = {
  matinee_shows: number;
  evening_shows: number;
  stage_crews: number;
  touring_production: boolean;
};

export const theatre_turnaround_score = (
  matineeShows: number,
  eveningShows: number,
  stageCrews: number,
  touringProduction: boolean,
) => {
  const baseResetMinutes = matineeShows * 18 + eveningShows * 27;
  const touringMinutes = touringProduction ? stageCrews * 6 : 0;
  const requiredMinutes = baseResetMinutes + touringMinutes;
  const crewCapacityMinutes = stageCrews * 45;
  const coveredMinutes = Math.min(requiredMinutes, crewCapacityMinutes);
  const delayedMinutes = Math.max(requiredMinutes - crewCapacityMinutes, 0);
  const handoffWindows = Math.floor(requiredMinutes / 30);

  return coveredMinutes + delayedMinutes * 8 + handoffWindows * 11;
};

export const score = theatre_turnaround_score;

export const handle = (value: RequestInput) => {
  const baseResetMinutes = value.matinee_shows * 18 + value.evening_shows * 27;
  const touringMinutes = value.touring_production ? value.stage_crews * 6 : 0;
  const requiredMinutes = baseResetMinutes + touringMinutes;
  const crewCapacityMinutes = value.stage_crews * 45;
  const delayedMinutes = Math.max(requiredMinutes - crewCapacityMinutes, 0);

  return {
    show_total: value.matinee_shows + value.evening_shows,
    base_reset_minutes: baseResetMinutes,
    touring_minutes: touringMinutes,
    required_minutes: requiredMinutes,
    crew_capacity_minutes: crewCapacityMinutes,
    covered_minutes: Math.min(requiredMinutes, crewCapacityMinutes),
    delayed_minutes: delayedMinutes,
    handoff_windows: Math.floor(requiredMinutes / 30),
    turnaround_score: theatre_turnaround_score(
      value.matinee_shows,
      value.evening_shows,
      value.stage_crews,
      value.touring_production,
    ),
    turnaround_state:
      delayedMinutes === 0
        ? "on_time"
        : value.touring_production
          ? "touring_delay"
          : "repertory_delay",
  };
};

export async function loadParley() {
  return { theatre_turnaround_score };
}

