export type RequestInput = {
  shore_packets: number;
  vessel_packets: number;
  relay_nodes: number;
  storm_routing: boolean;
};

export const handle = (value: RequestInput) => {
  const shore_units = value.shore_packets * 4;
  const vessel_units = value.vessel_packets * 7;
  const storm_units = value.storm_routing ? value.relay_nodes * 5 : 0;
  const required_units = shore_units + vessel_units + storm_units;
  const relay_capacity_units = value.relay_nodes * 24;
  const forwarded_units = Math.min(required_units, relay_capacity_units);
  const dropped_units = Math.max(required_units - relay_capacity_units, 0);
  const reserve_units = Math.max(relay_capacity_units - forwarded_units, 0);

  return {
    packet_total: value.shore_packets + value.vessel_packets,
    shore_units,
    vessel_units,
    storm_units,
    required_units,
    relay_capacity_units,
    forwarded_units,
    dropped_units,
    reserve_units,
    relay_state:
      dropped_units === 0
        ? "clear"
        : value.storm_routing
          ? "storm_loss"
          : "packet_loss",
  };
};

export const reserve = (
  shore_packets: number,
  vessel_packets: number,
  relay_nodes: number,
  storm_routing: boolean,
) =>
  handle({ shore_packets, vessel_packets, relay_nodes, storm_routing })
    .reserve_units;

export async function loadParley() {
  return {
    subsea_relay_reserve: (
      shore_packets: number,
      vessel_packets: number,
      relay_nodes: number,
      storm_routing: boolean,
    ) => BigInt(reserve(shore_packets, vessel_packets, relay_nodes, storm_routing)),
  };
}

