export type RequestInput={shore_packets:number;vessel_packets:number;relay_nodes:number;storm_routing:boolean};export const reserve=(s:number,v:number,n:number,t:boolean)=>{const b=s*4+v*7,r=Math.max(b-(t?n*5:0),0);return Math.max(n*24-Math.min(r,n*24),0)};export const handle=(v:RequestInput)=>{const s=v.shore_packets*4,x=v.vessel_packets*7,t=v.storm_routing?v.relay_nodes*5:0,r=s+x+t,c=v.relay_nodes*24,d=Math.max(r-c,0);return {packet_total:v.shore_packets+v.vessel_packets,shore_units:s,vessel_units:x,storm_units:t,required_units:r,relay_capacity_units:c,forwarded_units:Math.min(r,c),dropped_units:d,reserve_units:reserve(v.shore_packets,v.vessel_packets,v.relay_nodes,v.storm_routing),relay_state:d===0?'clear':v.storm_routing?'storm_loss':'packet_loss'}};export async function loadParley(){return {subsea_relay_reserve:(a:number,b:number,c:number,d:boolean)=>BigInt(reserve(a,b,c,d))}}
