    let archive_megabytes = speech_megabytes + music_megabytes + translation_megabytes;
    let replica_megabytes = archive_megabytes * value.language_tracks;
    let upload_blocks = archive_megabytes / 64;

    ResponseOutput {
        segment_total: value.spoken_segments + value.music_segments,
        speech_megabytes,
        music_megabytes,
        translation_megabytes,
        archive_megabytes,
        replica_megabytes,
        upload_blocks,
