const radioArchiveScore = (
  spokenSegments,
  musicSegments,
  languageTracks,
  liveBroadcast,
) => {
  const segmentTotal = spokenSegments + musicSegments;
  const speechMegabytes = spokenSegments * 14;
  const musicMegabytes = musicSegments * 24;
  const translationMegabytes = liveBroadcast ? languageTracks * 9 : 0;
  const archiveMegabytes =
    speechMegabytes + musicMegabytes + translationMegabytes;
  const replicaMegabytes = archiveMegabytes * languageTracks;
  const uploadBlocks = Math.floor(archiveMegabytes / 64);

  return replicaMegabytes + uploadBlocks * 17 + segmentTotal * 3;
};

export async function loadParley() { return { radio_archive_score: radioArchiveScore }; }

