use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub matinee_shows: i64,
    pub evening_shows: i64,
    pub stage_crews: i64,
    pub touring_production: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.matinee_shows >= 0 && self.evening_shows >= 0 && self.stage_crews >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub show_total: i64,
    pub base_reset_minutes: i64,
    pub touring_minutes: i64,
    pub required_minutes: i64,
    pub crew_capacity_minutes: i64,
    pub covered_minutes: i64,
    pub delayed_minutes: i64,
    pub handoff_windows: i64,
    pub turnaround_score: i64,
    pub turnaround_state: String,
}

pub fn score(matinee_shows: i64, evening_shows: i64, stage_crews: i64, touring: bool) -> i64 {
    let base_reset_minutes = matinee_shows * 18 + evening_shows * 27;
    let touring_minutes = if touring { stage_crews * 6 } else { 0 };
    let required_minutes = base_reset_minutes + touring_minutes;
    let crew_capacity_minutes = stage_crews * 45;
    let covered_minutes = required_minutes.min(crew_capacity_minutes);
    let delayed_minutes = (required_minutes - crew_capacity_minutes).max(0);
    let handoff_windows = required_minutes / 30;

    covered_minutes + delayed_minutes * 8 + handoff_windows * 11
}

pub fn handle(input: RequestInput) -> ResponseOutput {
    let base_reset_minutes = input.matinee_shows * 18 + input.evening_shows * 27;
    let touring_minutes = if input.touring_production {
        input.stage_crews * 6
    } else {
        0
    };
    let required_minutes = base_reset_minutes + touring_minutes;
    let crew_capacity_minutes = input.stage_crews * 45;
    let covered_minutes = required_minutes.min(crew_capacity_minutes);
    let delayed_minutes = (required_minutes - crew_capacity_minutes).max(0);
    let handoff_windows = required_minutes / 30;
    let turnaround_score = covered_minutes + delayed_minutes * 8 + handoff_windows * 11;
    let turnaround_state = if delayed_minutes == 0 {
        "on_time"
    } else if input.touring_production {
        "touring_delay"
    } else {
        "repertory_delay"
    };

    ResponseOutput {
        show_total: input.matinee_shows + input.evening_shows,
        base_reset_minutes,
        touring_minutes,
        required_minutes,
        crew_capacity_minutes,
        covered_minutes,
        delayed_minutes,
        handoff_windows,
        turnaround_score,
        turnaround_state: turnaround_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_theatre_turnaround_score(
    matinee_shows: i64,
    evening_shows: i64,
    stage_crews: i64,
    touring_production: i32,
) -> i64 {
    score(
        matinee_shows,
        evening_shows,
        stage_crews,
        touring_production != 0,
    )
}

