const theatreTurnaroundScore = (matineeShows, eveningShows, stageCrews, touringProduction) => {
  const baseResetMinutes = matineeShows * 18 + eveningShows * 27;
  const touringMinutes = touringProduction ? stageCrews * 6 : 0;
  const requiredMinutes = baseResetMinutes + touringMinutes;
  const crewCapacityMinutes = stageCrews * 45;
  const coveredMinutes = Math.min(requiredMinutes, crewCapacityMinutes);
  const delayedMinutes = Math.max(requiredMinutes - crewCapacityMinutes, 0);
  const handoffWindows = Math.floor(requiredMinutes / 30);
  return coveredMinutes + delayedMinutes * 8 + handoffWindows * 11;
};
export async function loadParley() { return { theatre_turnaround_score: theatreTurnaroundScore }; }

