use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub spoken_segments: i64,
    pub music_segments: i64,
    pub language_tracks: i64,
    pub live_broadcast: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.spoken_segments >= 0 && self.music_segments >= 0 && self.language_tracks >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub segment_total: i64,
    pub speech_megabytes: i64,
    pub music_megabytes: i64,
    pub translation_megabytes: i64,
    pub archive_megabytes: i64,
    pub replica_megabytes: i64,
    pub upload_blocks: i64,
    pub archive_score: i64,
    pub archive_mode: String,
}

pub fn score(spoken_segments: i64, music_segments: i64, language_tracks: i64, live_broadcast: bool) -> i64 {
    let speech_megabytes = spoken_segments * 14;
    let music_megabytes = music_segments * 24;
    let translation_megabytes = if live_broadcast { language_tracks * 9 } else { 0 };
    let archive_megabytes = speech_megabytes + music_megabytes + translation_megabytes;
    let replica_megabytes = archive_megabytes * language_tracks;
    let upload_blocks = archive_megabytes / 64;
    let segment_total = spoken_segments + music_segments;
    replica_megabytes + upload_blocks * 17 + segment_total * 3
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let speech_megabytes = v.spoken_segments * 14;
    let music_megabytes = v.music_segments * 24;
    let translation_megabytes = if v.live_broadcast { v.language_tracks * 9 } else { 0 };
    let archive_megabytes = speech_megabytes + music_megabytes + translation_megabytes;
    let replica_megabytes = archive_megabytes * v.language_tracks;
    let upload_blocks = archive_megabytes / 64;
    let segment_total = v.spoken_segments + v.music_segments;
    let archive_mode = if v.live_broadcast && v.language_tracks > 1 {
        "multilingual_live"
    } else if v.live_broadcast {
        "live"
    } else {
        "catalog"
    };

    ResponseOutput {
        segment_total,
        speech_megabytes,
        music_megabytes,
        translation_megabytes,
        archive_megabytes,
        replica_megabytes,
        upload_blocks,
        archive_score: score(v.spoken_segments, v.music_segments, v.language_tracks, v.live_broadcast),
        archive_mode: archive_mode.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_radio_archive_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

