export type RequestInput = {
  shore_packets: number;
  vessel_packets: number;
  relay_nodes: number;
  storm_routing: boolean;
};

export const reserve = (shorePackets: number, vesselPackets: number, relayNodes: number, stormRouting: boolean) => {
  const requiredUnits = shorePackets * 4 + vesselPackets * 7 + (stormRouting ? relayNodes * 5 : 0);
  const relayCapacityUnits = relayNodes * 24;
  const forwardedUnits = Math.min(requiredUnits, relayCapacityUnits);
  return Math.max(relayCapacityUnits - forwardedUnits, 0);
};

export const handle = (value: RequestInput) => {
  const shoreUnits = value.shore_packets * 4;
  const vesselUnits = value.vessel_packets * 7;
  const stormUnits = value.storm_routing ? value.relay_nodes * 5 : 0;
  const requiredUnits = shoreUnits + vesselUnits + stormUnits;
  const relayCapacityUnits = value.relay_nodes * 24;
  const forwardedUnits = Math.min(requiredUnits, relayCapacityUnits);
  const droppedUnits = Math.max(requiredUnits - relayCapacityUnits, 0);

  return {
    packet_total: value.shore_packets + value.vessel_packets,
    shore_units: shoreUnits,
    vessel_units: vesselUnits,
    storm_units: stormUnits,
    required_units: requiredUnits,
    relay_capacity_units: relayCapacityUnits,
    forwarded_units: forwardedUnits,
    dropped_units: droppedUnits,
    reserve_units: Math.max(relayCapacityUnits - forwardedUnits, 0),
    relay_state: droppedUnits === 0 ? "clear" : value.storm_routing ? "storm_loss" : "packet_loss",
  };
};

export async function loadParley() {
  return {
    subsea_relay_reserve: reserve,
  };
}

