const radioArchiveScore = (spokenSegments, musicSegments, languageTracks, liveBroadcast) => {
  const speechMegabytes = spokenSegments * 14n;
  const musicMegabytes = musicSegments * 24n;
  const translationMegabytes = liveBroadcast ? languageTracks * 9n : 0n;
  const archiveMegabytes = speechMegabytes + musicMegabytes + translationMegabytes;
  return archiveMegabytes * languageTracks
    + (archiveMegabytes / 64n) * 17n
