const radioArchiveScore = (spokenSegments, musicSegments, languageTracks, liveBroadcast) => {
  const spoken = BigInt(spokenSegments);
  const music = BigInt(musicSegments);
  const languages = BigInt(languageTracks);
  const segmentTotal = spoken + music;
  const speechMegabytes = spoken * 14n;
  const musicMegabytes = music * 24n;
  const translationMegabytes = liveBroadcast ? languages * 9n : 0n;
  const archiveMegabytes = speechMegabytes + musicMegabytes + translationMegabytes;
  const replicaMegabytes = archiveMegabytes * languages;
  const uploadBlocks = archiveMegabytes / 64n;
  return replicaMegabytes + uploadBlocks * 17n + segmentTotal * 3n;
};
export async function loadParley() { return { radio_archive_score: radioArchiveScore }; }

