use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub matinee_shows: i64,
    pub evening_shows: i64,
    pub stage_crews: i64,
    pub touring_production: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.matinee_shows >= 0 && self.evening_shows >= 0 && self.stage_crews >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub show_total: i64,
    pub base_reset_minutes: i64,
    pub touring_minutes: i64,
    pub required_minutes: i64,
    pub crew_capacity_minutes: i64,
    pub covered_minutes: i64,
    pub delayed_minutes: i64,
    pub handoff_windows: i64,
    pub turnaround_score: i64,
    pub turnaround_state: String,
}

pub fn score(matinee_shows: i64, evening_shows: i64, stage_crews: i64, touring_production: bool) -> i64 {
    let base_reset_minutes = matinee_shows * 18 + evening_shows * 27;
    let touring_minutes = if touring_production { stage_crews * 6 } else { 0 };
    let required_minutes = base_reset_minutes + touring_minutes;
    let crew_capacity_minutes = stage_crews * 45;
    let covered_minutes = required_minutes.min(crew_capacity_minutes);
    let delayed_minutes = (required_minutes - crew_capacity_minutes).max(0);
    let handoff_windows = required_minutes / 30;

    covered_minutes + delayed_minutes * 8 + handoff_windows * 11
}

pub fn handle(v: RequestInput) -> ResponseOutput {
    let base_reset_minutes = v.matinee_shows * 18 + v.evening_shows * 27;
    let touring_minutes = if v.touring_production { v.stage_crews * 6 } else { 0 };
    let required_minutes = base_reset_minutes + touring_minutes;
    let crew_capacity_minutes = v.stage_crews * 45;
    let covered_minutes = required_minutes.min(crew_capacity_minutes);
    let delayed_minutes = (required_minutes - crew_capacity_minutes).max(0);

    ResponseOutput {
        show_total: v.matinee_shows + v.evening_shows,
        base_reset_minutes,
        touring_minutes,
        required_minutes,
        crew_capacity_minutes,
        covered_minutes,
        delayed_minutes,
        handoff_windows: required_minutes / 30,
        turnaround_score: score(v.matinee_shows, v.evening_shows, v.stage_crews, v.touring_production),
        turnaround_state: if delayed_minutes == 0 {
            "on_time".into()
        } else if v.touring_production {
            "touring_delay".into()
        } else {
            "repertory_delay".into()
        },
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_theatre_turnaround_score(a: i64, b: i64, c: i64, d: i32) -> i64 {
    score(a, b, c, d != 0)
}

