use serde::{Deserialize, Serialize};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RequestInput {
    pub shore_packets: i64,
    pub vessel_packets: i64,
    pub relay_nodes: i64,
    pub storm_routing: bool,
}

impl RequestInput {
    pub fn valid(&self) -> bool {
        self.shore_packets >= 0 && self.vessel_packets >= 0 && self.relay_nodes >= 0
    }
}

#[derive(Serialize)]
pub struct ResponseOutput {
    pub packet_total: i64,
    pub shore_units: i64,
    pub vessel_units: i64,
    pub storm_units: i64,
    pub required_units: i64,
    pub relay_capacity_units: i64,
    pub forwarded_units: i64,
    pub dropped_units: i64,
    pub reserve_units: i64,
    pub relay_state: String,
}

pub fn reserve(shore_packets: i64, vessel_packets: i64, relay_nodes: i64, storm_routing: bool) -> i64 {
    let shore_units = shore_packets * 4;
    let vessel_units = vessel_packets * 7;
    let storm_units = if storm_routing { relay_nodes * 5 } else { 0 };
    let required_units = shore_units + vessel_units + storm_units;
    let relay_capacity_units = relay_nodes * 24;
    let forwarded_units = required_units.min(relay_capacity_units);

    (relay_capacity_units - forwarded_units).max(0)
}

pub fn handle(value: RequestInput) -> ResponseOutput {
    let shore_units = value.shore_packets * 4;
    let vessel_units = value.vessel_packets * 7;
    let storm_units = if value.storm_routing { value.relay_nodes * 5 } else { 0 };
    let required_units = shore_units + vessel_units + storm_units;
    let relay_capacity_units = value.relay_nodes * 24;
    let forwarded_units = required_units.min(relay_capacity_units);
    let dropped_units = (required_units - relay_capacity_units).max(0);
    let reserve_units = (relay_capacity_units - forwarded_units).max(0);
    let relay_state = if dropped_units == 0 {
        "clear"
    } else if value.storm_routing {
        "storm_loss"
    } else {
        "packet_loss"
    };

    ResponseOutput {
        packet_total: value.shore_packets + value.vessel_packets,
        shore_units,
        vessel_units,
        storm_units,
        required_units,
        relay_capacity_units,
        forwarded_units,
        dropped_units,
        reserve_units,
        relay_state: relay_state.into(),
    }
}

#[unsafe(no_mangle)]
pub extern "C" fn parley_subsea_relay_reserve(a: i64, b: i64, c: i64, d: i32) -> i64 {
    reserve(a, b, c, d != 0)
}

