class RequestInput(BaseModel):
 model_config=ConfigDict(extra='forbid',strict=True); shore_packets:int=Field(ge=0); vessel_packets:int=Field(ge=0); relay_nodes:int=Field(ge=0); storm_routing:bool
def subsea_relay_reserve(s:int,v:int,n:int,t:bool)->int:
 shore_units = s * 4
 vessel_units = v * 7
 storm_units = n * 5 if t else 0
 required_units = shore_units + vessel_units + storm_units
 relay_capacity_units = n * 24
 forwarded_units = min(required_units, relay_capacity_units)
 return max(relay_capacity_units - forwarded_units, 0)
